function Brand({ light = false }: { light?: boolean }) {
  return <div className={`brand ${light ? 'brand-light' : ''}`}><span className="brand-mark"><Zap size={21} fill="currentColor" /></span><span>PlugPlan<span className="brand-sg">SG</span></span></div>;
}
function Button({ children, className = '', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement>) { return <button className={`button ${className}`} {...props}>{children}</button>; }
function Field({ label, hint, error, children }: { label: string; hint?: string; error?: string; children: ReactNode }) { return <div className={`field ${error ? 'field-invalid' : ''}`}><div className="field-label">{label}</div>{children}{hint && <span className="field-hint">{hint}</span>}{error && <span className="field-error" role="alert">{error}</span>}</div>; }
